def compute(vars):
    values = [vars["v1"], vars["v2"]]
    largest = max(values)
    smallest = min(values)
    difference = largest - smallest
    return {
        "value": difference,
        "trace": {
            "largest": largest,
            "smallest": smallest,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
